// 0 -> 3.0 V in 0.5 V steps (1 s each), hold 5 s, then reverse at -3.0 V.
const seq = [0, 0.5, 1.0, 1.5, 2.0, 2.5, 3.0, 3.0, 3.0, 3.0, 3.0, 3.0, -3.0];
let i = context.get('step') || 0;
if (i >= seq.length) return null;
context.set('step', i + 1);
msg.payload = { voltage: seq[i] };
return msg;

// Recover from a fault: stop the motor first, then clear the latched fault.
if (msg.payload && msg.payload.fault) {
    const names = ['ocp', 'uvlo', 'ots', 'ilimit'].filter((k) => msg.payload[k]);
    node.warn('DRV8830 fault: ' + names.join(', '));
    return [[{ payload: { stop: true } }, { payload: { clear_fault: true } }], msg];
}
return [null, msg];
